#!/usr/bin/env python3
"""Build the static Nocturne deck. Use --ready only after all artwork is present."""
import argparse, html, json, re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
E=html.escape
p=argparse.ArgumentParser(); p.add_argument('--ready',action='store_true'); args=p.parse_args()
DATA=ROOT/'decks/gothic/content.json'
cards=json.loads(DATA.read_text())
assert len(cards)==78 and len({c['id'] for c in cards})==78
ready=args.ready
if ready:
    assert all((ROOT/c['image'].lstrip('/')).is_file() for c in cards)
    assert (ROOT/'cards/gothic/back.webp').is_file()
spec=dict(id='nocturne-gothic',name='Nocturne Cathedral Tarot',shortName='Gothic Tarot',order=1,ready=ready,gallery='/decks/gothic',back='/cards/gothic/back.webp',description='An original 78-card journey through moonlit cathedrals, silver shadows, and quiet courage.',cards=cards)
(ROOT/'decks/gothic/cards.js').write_text('/* Generated by scripts/build-gothic.py; edit content.json. */\nCardDecks.register('+json.dumps(spec,ensure_ascii=False,separators=(',',':'))+');\n')
nav='<header class="site-header"><a class="brand" href="/">The Cat Priestess<span>Moonlight · intuition · wonder</span></a><nav aria-label="Main"><a href="/decks">Collections</a><a href="/deck">Original oracle</a><a href="/deck/print.html">Print the oracle</a><a href="/?deck=nocturne-gothic#readings">Draw cards</a></nav></header>'
foot='<footer><p>Nocturne Cathedral Tarot · The Cat Priestess</p><p>Original AI-assisted illustrations and interpretations created for this collection. The IVOSART oracle and its printable editions remain a separate collection.</p><nav aria-label="Footer"><a href="/about">About</a><a href="/privacy">Privacy</a><a href="/contact">Contact</a><a href="/">Ask Bastet</a></nav></footer>'
def page(title,desc,path,body,image='/cards/gothic/the-high-priestess.webp'):
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{E(title)} | The Cat Priestess</title><meta name="description" content="{E(desc,quote=True)}"><link rel="canonical" href="https://www.thecatpriestess.com{path}">
<meta name="theme-color" content="#090b13"><meta property="og:title" content="{E(title,quote=True)}"><meta property="og:description" content="{E(desc,quote=True)}"><meta property="og:url" content="https://www.thecatpriestess.com{path}"><meta property="og:image" content="https://www.thecatpriestess.com{image}"><meta property="og:type" content="website"><meta name="twitter:card" content="summary_large_image">
<link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/decks/gothic/gothic.css"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cinzel:wght@400;600;700&family=Cormorant+Garamond:ital,wght@0,400;0,600;1,400&display=swap" rel="stylesheet"><script src="/consent.js" defer></script><script src="/decks/gothic/gallery.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a>{nav}<main id="main" class="wrap">{body}</main>{foot}</body></html>'''
def art(c,lazy=True):
    return f'<div class="art"><img src="{c["image"]}" alt="{E(c["alt"],quote=True)}" width="896" height="1344" {"loading=lazy" if lazy else "fetchpriority=high"}><span class="art-error" hidden>Illustration unavailable. The full card interpretation is below.</span></div>'
for i,c in enumerate(cards):
    prev,nxt=cards[(i-1)%78],cards[(i+1)%78]
    body=f'''<div class="breadcrumb"><a href="/decks">Collections</a> / <a href="/decks/gothic">Nocturne Cathedral</a> / {E(c['name'])}</div><article class="detail">{art(c,False)}<div class="detail-copy"><p class="eyebrow">{E(c['arcana'])} Arcana · {E(c['rn'])}{' · '+c['suit'] if c['suit'] else ''}</p><h1>{E(c['name'])}</h1><p class="keywords">{E(' · '.join(c['keywords']))}</p><p class="affirmation">“{E(c['aff'][0])}”</p><section><h2>Upright</h2><p>{E(c['up'])}</p></section><section><h2>Reversed</h2><p>{E(c['rev'])}</p></section><section><h2>Within the image</h2><p>{E(c['symbolism'])}</p></section><section class="reflection"><h2>A question to carry</h2><p>{E(c['question'])}</p></section><p class="credit">Original AI-assisted illustration · {"Finished" if ready else "Artwork in preparation"}. Titles and numbers are set in live type for clear, consistent reading.</p><a class="button" href="/?deck=nocturne-gothic#readings">Read with this collection</a></div></article><nav class="card-nav" aria-label="Adjacent cards"><a href="/decks/gothic/{prev['id']}">← {E(prev['name'])}</a><a href="/decks/gothic">All 78 cards</a><a href="/decks/gothic/{nxt['id']}">{E(nxt['name'])} →</a></nav>'''
    (ROOT/f'decks/gothic/{c["id"]}.html').write_text(page(c['name']+' — Nocturne Cathedral Tarot',c['up'],f'/decks/gothic/{c["id"]}',body,c['image']))
grid=''.join(f'<article class="gallery-card" data-group="{c["suit"] or "Major"}" data-search="{E((c["name"]+" "+" ".join(c["keywords"])).lower(),quote=True)}"><a href="/decks/gothic/{c["id"]}">{art(c)}<div class="caption"><span>{E(c["rn"])} · {c["suit"] or "Major Arcana"}</span><h2>{E(c["name"])}</h2></div></a></article>' for c in cards)
filters=''.join(f'<button type="button" data-filter="{s}" aria-pressed="{"true" if s=="All" else "false"}">{s}</button>' for s in ['All','Major','Wands','Cups','Swords','Pentacles'])
body=f'''<section class="hero"><div><p class="eyebrow">A new collection · 78 original cards</p><h1>Nocturne<br>Cathedral Tarot</h1><p class="intro">Where the cathedral ends, the inner journey begins. Walk beneath silver arches, follow the animals of the night, and let a little moonlight find what words cannot.</p><a class="button" href="/?deck=nocturne-gothic#readings">Enter a reading</a><p class="small">22 Major Arcana · 56 Minor Arcana · one shared, reversible back</p></div><figure class="hero-art">{art(cards[2],False)}<figcaption>The High Priestess · Keeper of the threshold</figcaption></figure></section><section class="gallery-section" aria-labelledby="gallery-title"><div class="section-heading"><p class="eyebrow">The illuminated archive</p><h2 id="gallery-title">Every shadow has a story</h2><p>Explore each card’s upright and reversed meanings, symbolism, and reflection. All illustrations are original AI-assisted artworks made for The Cat Priestess.</p></div><div class="filters" role="group" aria-label="Filter by arcana or suit">{filters}</div><label class="search-label" for="cardSearch">Find a card or theme</label><input id="cardSearch" type="search" placeholder="Try The Moon, courage, or renewal" autocomplete="off"><p id="resultCount" class="small" role="status" aria-live="polite">78 cards</p><div class="gallery-grid">{grid}</div><p id="noResults" hidden>No cards match your search. Try another name or theme.</p><noscript><p>All cards are displayed below. Open any card to read its interpretation.</p></noscript></section><section class="back-story"><div><p class="eyebrow">The other side of the veil</p><h2>A common sky</h2><p>Mirrored cats keep watch around a celestial rose window. The shared back has no upright direction, so the next revelation stays private until you turn the card.</p><p class="small">{('All 78 fronts and the matching back are finished illustrations; there are no artwork placeholders.' if ready else 'This development checkpoint is awaiting the remaining finished illustrations.')}</p></div><figure><img src="/cards/gothic/back.webp" width="896" height="1344" loading="lazy" alt="Reversible Gothic card back with mirrored cats around a celestial rose window"></figure></section>'''
(ROOT/'decks/gothic/index.html').write_text(page('Nocturne Cathedral Tarot — Gothic Gallery','Explore 78 original Gothic Tarot cards: moonlit architecture, symbolic animals, dark fantasy, and individual upright and reversed interpretations.','/decks/gothic',body))
body='''<section class="collection-intro"><p class="eyebrow">The Cat Priestess</p><h1>Choose your collection</h1><p>Different worlds, the same quiet invitation. Each collection has its own artwork and interpretations. Read with one, or wander through its gallery.</p></section><div class="collections"><article><a href="/deck"><img src="/cards/05.webp" width="1024" height="1536" alt="The Inner World, from the original IVOSART oracle" loading="lazy"></a><div><p class="eyebrow">The original · 34 cards</p><h2>The IVOSART Oracle</h2><p>The original collection illustrated by IVOSART, with its familiar affirmations and gentle counsel.</p><a class="button" href="/?deck=ivosart-oracle#readings">Draw the oracle</a><p><a href="/deck">Explore the gallery</a> · <a href="/deck/print.html">Printable editions</a></p></div></article><article><a href="/decks/gothic"><img src="/cards/gothic/the-high-priestess.webp" width="896" height="1344" alt="The High Priestess of Nocturne Cathedral Tarot" loading="lazy"></a><div><p class="eyebrow">A new journey · 78 cards</p><h2>Nocturne Cathedral Tarot</h2><p>An original Gothic Tarot of moonlit sanctuaries, mysterious figures, and the animals who guide us through the dark.</p><a class="button" href="/?deck=nocturne-gothic#readings">Draw Gothic Tarot</a><p><a href="/decks/gothic">Explore all 78 cards</a></p></div></article></div>'''
(ROOT/'decks/index.html').write_text(page('Tarot & Oracle Collections','Choose the original 34-card IVOSART oracle or the new 78-card Nocturne Cathedral Gothic Tarot.','/decks',body))
smap=ROOT/'sitemap.xml'; original=re.sub(r'  <url>\s*<loc>https://www.thecatpriestess.com/decks(?:/[^<]*)?</loc>.*?</url>\s*','',smap.read_text(),flags=re.S)
urls=['/decks','/decks/gothic']+['/decks/gothic/'+c['id'] for c in cards]
smap.write_text(original.replace('</urlset>',''.join(f'  <url><loc>https://www.thecatpriestess.com{u}</loc><lastmod>2026-10-15</lastmod><changefreq>monthly</changefreq><priority>0.6</priority></url>\n' for u in urls)+'</urlset>\n'))
print(f'Built {len(cards)} cards; ready={ready}')
